          pool, sizeof(amqp_connection_start_t));
      if (m == NULL) {
        return AMQP_STATUS_NO_MEMORY;
      }
      if (!amqp_decode_8(encoded, &offset, &m->version_major))
        return AMQP_STATUS_BAD_AMQP_DATA;
      if (!amqp_decode_8(encoded, &offset, &m->version_minor))
        return AMQP_STATUS_BAD_AMQP_DATA;
